content.content:
.aq-insp-title {
    font-size: 11.5px;
    font-weight: 600;
    color: var(--aq-text-muted);
}

.aq-kv {
    display: grid;
    grid-template-columns: 110px 1fr;
    row-gap: 8px;
    column-gap: 8px;
    font-size: 12.5px;
    margin: 0;
    align-items: start;
}

.aq-kv dt {
    color: var(--aq-text-muted);
    margin: 0;
}

.aq-kv dd {
    margin: 0;
    font-variant-numeric: tabular-nums;
    min-width: 0;
    overflow-wrap: anywhere;
}

.aq-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 20px;
    padding: 0 8px;
    border-radius: 10px;
    font-size: 11.5px;
    font-weight: 500;
    white-space: nowrap;
}

.aq-badge::before {

